import{_ as t,o as a,c as r,ap as n}from"./chunks/framework.CuFS6FqL.js";const h=JSON.parse('{"title":"Data protection and security","description":"How we handle customer data and protect evidence, notes, and reports during pentests.","frontmatter":{"title":"Data protection and security","description":"How we handle customer data and protect evidence, notes, and reports during pentests."},"headers":[],"relativePath":"data-protection.md","filePath":"data-protection.md"}'),o={name:"data-protection.md"};function i(s,e,p,d,c,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /data-protection.md for this page in Markdown format</div><h1 id="data-protection-and-security" tabindex="-1">Data protection and security <a class="header-anchor" href="#data-protection-and-security" aria-label="Permalink to &quot;Data protection and security&quot;">​</a></h1><p>We manage our notes and reports in our self-developed pentest reporting solution SysReptor (which we distribute internationally to pentesting teams; source-available on <a href="https://github.com/syslifters/sysreptor/" target="_blank" rel="noreferrer">GitHub</a>). The assignment of permissions to projects always follows the need-to-know principle. Stored data such as images, evidence, and database entries are encrypted on the server side (Encrypted Data at Rest; see also the <a href="https://docs.sysreptor.com/setup/configuration/#data-encryption-at-rest" target="_blank" rel="noreferrer">SysReptor documentation</a>), and transmission (Data in Transit) is likewise encrypted (via TLS/HTTPS).</p><p>Three months after a (re-)test has been completed, the reports, notes, and evidence are encrypted and can only be restored using hardware tokens and a four-eyes principle (encryption utilizing Shamir&#39;s Secret Sharing algorithm; further information: <a href="https://docs.sysreptor.com/insights/archiving/" target="_blank" rel="noreferrer">https://docs.sysreptor.com/insights/archiving/</a>), until they are automatically deleted upon expiration of our retention periods.</p><p>Communication between components of our internal networks is end-to-end encrypted (utilizing a Tailscale VPN; sometimes with multiple encryption layers).</p><p>We provide each pentester with a smartphone featuring a dedicated business number as well as a computer. Private use is prohibited for security and data protection reasons. Members of project teams communicate via Signal Messenger using disappearing messages. We protect company computers with IKARUS / HarfangLab (endpoint protection, detection, and vulnerability management).</p><p>All web pentest activities are logged via the pentesters&#39; local proxy servers (<a href="https://portswigger.net/burp" target="_blank" rel="noreferrer">PortSwigger Burp</a>) and deleted three months after completion of the pentests or re-tests.</p><p>In addition, we have non-disclosure agreements in place with our employees.</p>',8)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
